SET NAMES utf8mb4;

-- ── hp_cache_res_horoscope  [星座运势]  10 个文件 ────────────
DROP TABLE IF EXISTS `hp_cache_res_horoscope`;
CREATE TABLE `hp_cache_res_horoscope` (
  `asset_key` VARCHAR(191) NOT NULL COMMENT '缓存文件名',
  `body` LONGTEXT NOT NULL COMMENT '原始响应 JSON 全文',
  `cache_updated_at` BIGINT NOT NULL DEFAULT 1795791234763,
  `period_type` VARCHAR(8) NOT NULL DEFAULT 'year' COMMENT '时间粒度：day/month/year/static；星座固定按年',
  `period_key` VARCHAR(10) NOT NULL DEFAULT '' COMMENT '粒度日期：YYYY-MM-DD / YYYY-MM / YYYY；星座取当前年份，由回填与运行时写入',
  PRIMARY KEY (`asset_key`),
  KEY `idx_cache_period` (`period_type`, `period_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='星座运势响应';

